-- 08-edges.sql
--
-- Extracted from artifacts/v1/gaos-arcadedb-model.html, which is the source of
-- truth for this schema, THEN RECONCILED against ArcadeDB 26.7.2. This file is
-- not verbatim: see RECONCILIATION.md, deviation 1, for what changed and why.
--
-- Do not edit this file to change the model -- change the document, then
-- re-extract and re-reconcile. A deviation that lives only here is a schema
-- nobody reviewing the model document would ever see, which is exactly the
-- failure RECONCILIATION.md exists to prevent.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

-- Structural containment. UNIQUE stops a double-injection from creating a
-- second HAS_ISSUE between the same product and story.
CREATE EDGE TYPE OWNS            IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_REQUIREMENT IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_ISSUE       IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_CRITERION   IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_ARTIFACT    IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE TRACKS_METRIC   IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE USES_REPOSITORY IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_WORKFLOW    IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_TASK        IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_RUN         IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY HAS_TASK.ordinal      INTEGER;
CREATE PROPERTY HAS_CRITERION.ordinal INTEGER;
CREATE PROPERTY HAS_ARTIFACT.role     STRING;
CREATE PROPERTY USES_REPOSITORY.primary BOOLEAN (default false);

-- Code graph. CONTAINS is reused for Repository→File and File→Function;
-- both are strict containment, so one type keeps traversals uniform.
CREATE EDGE TYPE CONTAINS IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE CALLS    IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY CALLS.callCount INTEGER (default 1, min 1);

-- Planning. DEPENDS_ON points from the dependent task to its prerequisite:
--   Task -DEPENDS_ON-> Task   means the OUT side waits for the IN side.
-- Every readiness query in §12 assumes that direction.
CREATE EDGE TYPE DEPENDS_ON IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY DEPENDS_ON.kind STRING (default 'hard', regexp 'hard|soft|data|api');

CREATE EDGE TYPE IMPLEMENTS IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE SATISFIES  IF NOT EXISTS EXTENDS GaosEdge;

-- Execution. Bound to TaskRun, not Task, so each attempt keeps its own
-- agent, workspace, prompt and context.
CREATE EDGE TYPE EXECUTED_BY    IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE USES_WORKSPACE IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE USES_PROMPT    IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE ASSEMBLED      IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE MODIFIES       IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE GENERATES      IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY EXECUTED_BY.reservedAt    DATETIME;
CREATE PROPERTY USES_WORKSPACE.leaseUntil DATETIME;
CREATE PROPERTY USES_PROMPT.renderedHash  STRING;
CREATE PROPERTY MODIFIES.changeKind       STRING (regexp 'add|edit|delete|rename');
CREATE PROPERTY MODIFIES.linesAdded       INTEGER (min 0);
CREATE PROPERTY MODIFIES.linesRemoved     INTEGER (min 0);

-- The audit edge. role says why a node was in the prompt; weight and tokens
-- let you tune the assembler with evidence instead of intuition.
CREATE EDGE TYPE USES_CONTEXT IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY USES_CONTEXT.role   STRING (mandatory true, notnull true,
                 regexp 'requirement|rule|boundary|story|criterion|diagram|decision|lesson|code|diff|policy');
CREATE PROPERTY USES_CONTEXT.weight FLOAT   (min 0, max 1);
CREATE PROPERTY USES_CONTEXT.tokens INTEGER (min 0);

-- Judgment and memory.
CREATE EDGE TYPE REVIEWED_BY     IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE GATED_BY        IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE LEARNS_FROM     IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE APPLIES_TO      IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE PRODUCES        IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE HAS_PARTICIPANT IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE DISCUSSES       IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE GOVERNS         IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY APPLIES_TO.score           FLOAT  (min 0, max 1);
CREATE PROPERTY HAS_PARTICIPANT.meetingRole STRING
                 (regexp 'facilitator|recorder|architect|reviewer|planner|participant');

-- Capacity.
CREATE EDGE TYPE SEATED_IN   IF NOT EXISTS EXTENDS GaosEdge;
CREATE EDGE TYPE RESERVED_BY IF NOT EXISTS EXTENDS GaosEdge;
CREATE PROPERTY SEATED_IN.since DATETIME;
